sys_script_client.script:
function onSubmit() {
    var rollFrom = g_form.getValue('roll_from');
    var rollTo = g_form.getValue('roll_to');
    g_form.hideFieldMsg('roll_to', true);

    if (rollFrom && rollTo) {
        var numFrom = Number(rollFrom.trim());
        var numTo = Number(rollTo.trim());
        var isInvalid = false;

        if (!isNaN(numFrom) && !isNaN(numTo)) {
            if (numFrom >= numTo) {
                isInvalid = true;
            }
        } else {
            if (rollFrom.trim().localeCompare(rollTo.trim(), undefined, { numeric: true, sensitivity: 'base' }) >= 0) {
                isInvalid = true;
            }
        }

        if (isInvalid) {
            g_form.clearMessages();
            g_form.showFieldMsg('roll_to', 'Roll To must be greater than Roll From.', 'error');
            g_form.addErrorMessage('Roll From should be less than Roll To.');
            return false;
        }
    }
    return true;
}
